package local.skyfamily;
import android.app.AlertDialog;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Build;import android.provider.Settings;import android.view.*;import android.widget.*;
final class GestureSettings {
 static final String P="edgegesture.",ENABLED=P+"enabled";
 static boolean allowed(Context context){return Build.VERSION.SDK_INT>=23?Settings.canDrawOverlays(context):context.checkCallingOrSelfPermission(android.Manifest.permission.SYSTEM_ALERT_WINDOW)==PackageManager.PERMISSION_GRANTED;}
 static int number(android.content.SharedPreferences preferences,String key,int fallback,int min,int max){return Math.max(min,Math.min(max,preferences.getInt(P+key,fallback)));}
 static void ensure(PersonalActivity host){if(!host.prefs.getBoolean(ENABLED,false))return;if(!allowed(host)){EdgeGestureService.error="Overlay permission unavailable / enable it in Gesture settings";host.stopService(new Intent(host,EdgeGestureService.class));host.prefs.edit().putBoolean(ENABLED,false).commit();return;}send(host,"configure");}
 static void send(PersonalActivity host,String action){try{Intent intent=new Intent(host,EdgeGestureService.class).setAction(action);if(Build.VERSION.SDK_INT>=26)host.startForegroundService(intent);else host.startService(intent);}catch(Exception error){EdgeGestureService.error="Gesture service unavailable / "+error.getClass().getSimpleName();host.prefs.edit().putBoolean(ENABLED,false).commit();host.toast(EdgeGestureService.error);}}
 static void permission(PersonalActivity host){try{Intent intent=Build.VERSION.SDK_INT>=23?new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+host.getPackageName())):new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+host.getPackageName()));host.startActivity(intent);}catch(Exception error){host.toast("Overlay permission screen unavailable on this firmware");}}
 static boolean save(PersonalActivity host,android.content.SharedPreferences.Editor editor){boolean ok=editor.commit();if(!ok){host.toast("Gesture settings NOT SAVED / check storage");return false;}if(host.prefs.getBoolean(ENABLED,false))send(host,"configure");sync(host);return true;}
 static String actionLabel(Context context,String action){if(action.equals("none"))return "None";if(action.equals("legacydash"))return "Return to legacydash";try{ComponentName component=ComponentName.unflattenFromString(action);if(component==null)return "Unavailable app";ActivityInfo info=context.getPackageManager().getActivityInfo(component,0);return String.valueOf(info.loadLabel(context.getPackageManager()));}catch(Exception error){return "App unavailable / choose another";}}
 static void sync(PersonalActivity host){if(host.body==null)return;View toggle=host.body.findViewWithTag("gestures.enabled"),label=host.body.findViewWithTag("gestures.status");if(toggle instanceof CheckBox)((CheckBox)toggle).setChecked(host.prefs.getBoolean(ENABLED,false));if(label instanceof TextView)((TextView)label).setText(!allowed(host)?"Overlay permission is not granted":!EdgeGestureService.error.isEmpty()?EdgeGestureService.error:EdgeGestureService.instance!=null&&EdgeGestureService.instance.edge!=null?"Invisible edge service active":host.prefs.getBoolean(ENABLED,false)?"Starting / tap Refresh status":"Gestures disabled");}
 static void open(PersonalActivity host){host.page("Gesture settings");host.text("Opt-in invisible edge controls can remain over Skylight and other apps. The small trigger strip consumes touches that start inside it; other touches are not intercepted. No root or accessibility access is requested. Firmware can still block overlays or app launching.");CheckBox enabled=new CheckBox(host);enabled.setText("Enable invisible edge gestures across apps");enabled.setTag("gestures.enabled");enabled.setChecked(host.prefs.getBoolean(ENABLED,false));host.body.addView(enabled);TextView status=host.paperText("",16,PaperActivity.MUTE);status.setTag("gestures.status");host.body.addView(status);enabled.setOnCheckedChangeListener((button,checked)->{if(checked&&!allowed(host)){button.setChecked(false);permission(host);host.toast("Grant overlay permission, then enable gestures here");return;}if(host.prefs.getBoolean(ENABLED,false)==checked)return;if(!host.prefs.edit().putBoolean(ENABLED,checked).commit()){host.toast("Gesture setting NOT SAVED");return;}if(checked)send(host,"configure");else host.stopService(new Intent(host,EdgeGestureService.class));sync(host);});host.button("Overlay permission",()->permission(host));host.button("Refresh status",()->sync(host));host.section("Trigger area");choice(host,"Edge","side",new String[]{"Left","Right"},0);choice(host,"Position along edge","position",new String[]{"Top","Middle","Bottom"},1);slider(host,"Strip width","width",16,8,32);slider(host,"Strip height","height",160,80,320);slider(host,"Inward swipe travel","travel",64,32,160);host.section("Gesture actions");action(host,"Swipe inward","swipe","legacydash");action(host,"Double-tap edge","double","none");action(host,"Hold edge then release","hold","none");host.button("Test / show trigger for 10 seconds",()->{if(!host.prefs.getBoolean(ENABLED,false)){host.toast("Enable gestures first");return;}send(host,"test");});host.button("Disable edge gestures",()->{host.prefs.edit().putBoolean(ENABLED,false).commit();host.stopService(new Intent(host,EdgeGestureService.class));sync(host);});host.button("Reset gesture settings",()->new AlertDialog.Builder(host).setMessage("Disable and reset all edge gesture settings?").setPositiveButton("Reset",(dialog,which)->{android.content.SharedPreferences.Editor editor=host.prefs.edit();for(String key:host.prefs.getAll().keySet())if(key.startsWith(P))editor.remove(key);if(editor.commit()){host.stopService(new Intent(host,EdgeGestureService.class));EdgeGestureService.error="";open(host);}else host.toast("Reset NOT SAVED");}).setNegativeButton("Cancel",null).show());host.text("Swipe inward with one finger, finishing within 1.2 seconds. Hold means at least 650ms, then release. Test mode makes the strip temporarily visible and reports recognition instead of launching apps. Normal mode shows no handle or gesture trail, but an ongoing notification provides Disable. These are configurable predefined gestures, not recorded freeform shapes. No boot auto-start: open legacydash after reboot. No guarantee over lock screens, secure/system windows or vendor kiosk restrictions.");sync(host);}
 static void choice(PersonalActivity host,String label,String key,String[] values,int fallback){host.text(label);Spinner spinner=new Spinner(host);spinner.setAdapter(new ArrayAdapter<String>(host,android.R.layout.simple_spinner_dropdown_item,values));spinner.setSelection(number(host.prefs,key,fallback,0,values.length-1));host.body.addView(spinner);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int position,long id){if(number(host.prefs,key,fallback,0,values.length-1)!=position)save(host,host.prefs.edit().putInt(P+key,position));}});}
 static void slider(PersonalActivity host,String title,String key,int fallback,int min,int max){TextView label=host.paperText("",16,PaperActivity.INK);host.body.addView(label);SeekBar bar=new SeekBar(host);bar.setMax(max-min);bar.setProgress(number(host.prefs,key,fallback,min,max)-min);label.setText(title+" / "+(bar.getProgress()+min)+" dp");bar.setContentDescription(title);host.body.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar seek,int value,boolean user){label.setText(title+" / "+(value+min)+" dp");}public void onStartTrackingTouch(SeekBar seek){}public void onStopTrackingTouch(SeekBar seek){save(host,host.prefs.edit().putInt(P+key,seek.getProgress()+min));}});}
 static void action(PersonalActivity host,String title,String key,String fallback){TextView button=host.paperText(title+" / "+actionLabel(host,host.prefs.getString(P+key,fallback)),18,PaperActivity.INK);button.setMinHeight(host.dp(56));button.setBackground(host.controlBackground());button.setFocusable(true);host.body.addView(button);button.setOnClickListener(view->new AlertDialog.Builder(host).setTitle(title).setItems(new String[]{"None","Return to legacydash","Choose installed app"},(dialog,index)->{if(index==2){ShortcutPins.apps(host,(label,component)->{if(save(host,host.prefs.edit().putString(P+key,component)))button.setText(title+" / "+label);});return;}String value=index==0?"none":"legacydash";if(save(host,host.prefs.edit().putString(P+key,value)))button.setText(title+" / "+actionLabel(host,value));}).setNegativeButton("Cancel",null).show());}
}
